  "routes[route-dbz-gt-black-star-journey].localizedName": "Dragon Ball GT · Voyage spatial",
  "routes[route-dbz-gt-black-star-journey].group": "Dragon Ball GT",
  "routes[route-dbz-gt-black-star-journey].description": "Dragon Ball GT : de la Terre jusqu'aux confins de l'espace, le voyage de Goku, Trunks et Pan à la recherche des Dragon Balls noires, planète après planète dans l'ordre des visites — Imecka → Beehay → Gelbo (Luud) → planète-machine M-2 → Pital — jusqu'à la Nouvelle planète Plant de la saga de Baby, puis le retour sur Terre. Il couvre la carte de la Terre et la sous-carte « Espace (GT) ».",
  "routes[route-dbz-gt-black-star-journey].steps[0].label": "Départ de la Capsule Corporation",
  "routes[route-dbz-gt-black-star-journey].steps[0].description": "Goku enfant, Trunks et Pan s'envolent à bord du vaisseau spatial pour récupérer les Dragon Balls noires.",
  "routes[route-dbz-gt-black-star-journey].steps[1].label": "Route spatiale (GT)",
  "routes[route-dbz-gt-black-star-journey].steps[1].description": "Double-cliquez sur le repère « Espace (GT) » pour monter vers la sous-carte spatiale de GT.",
  "routes[route-dbz-gt-black-star-journey].steps[2].label": "1 · Départ de la Terre",
  "routes[route-dbz-gt-black-star-journey].steps[2].description": "Le vaisseau de la Capsule Corporation quitte la Terre.",
