  "routes[route-dbz-gt-black-star-journey].steps[3].description": "Première planète : affrontement avec Ledgic et Don Kee ; Gill rejoint le groupe.",
  "routes[route-dbz-gt-black-star-journey].steps[4].label": "3 · Planète Beehay",
  "routes[route-dbz-gt-black-star-journey].steps[4].description": "Une planète hostile peuplée de dragons et de créatures agressives, qui abrite une Dragon Ball noire.",
  "routes[route-dbz-gt-black-star-journey].steps[5].label": "4 · Planète Gelbo (Luud)",
  "routes[route-dbz-gt-black-star-journey].steps[5].description": "Le culte du dieu-machine Luud et le premier piège du Dr Myuu.",
  "routes[route-dbz-gt-black-star-journey].steps[6].label": "5 · Planète-machine M-2",
  "routes[route-dbz-gt-black-star-journey].steps[6].description": "Le général Rilldo, le laboratoire du Dr Myuu et la naissance de Baby.",
