  "routes[route-dbz-gt-black-star-journey].steps[8].label": "7 · Nouvelle planète Plant",
  "routes[route-dbz-gt-black-star-journey].steps[8].description": "Saga de Baby : sur la planète recréée pour les Tuffles, Goku Super Saiyan 4 bat Baby.",
  "routes[route-dbz-gt-black-star-journey].steps[9].label": "8 · Retour sur Terre",
  "routes[route-dbz-gt-black-star-journey].steps[9].description": "Double-cliquez sur « Terre » pour revenir à la carte principale.",
  "routes[route-dbz-gt-baby-journey].localizedName": "Dragon Ball GT · Saga de Baby",
  "routes[route-dbz-gt-baby-journey].group": "Dragon Ball GT",
  "routes[route-dbz-gt-baby-journey].description": "Dragon Ball GT : le parasite tuffle Baby possède Vegeta à la Capsule Corp., infecte toute la Terre et transfère la population sur la Nouvelle planète Plant, où Goku Super Saiyan 4 le bat. Couvre la carte de la Terre et la sous-carte « Espace (GT) ».",
